// Directive de l'éditeur du 02/11/2026 (DIRECTIVES.md, D52) : tout geste à faire à la main sur son PC lui est toujours dit.
// Ajoutée seulement aux lots qui n'avaient pas commencé à cette date, pour garder intactes les invites des lots déjà faits (reprise).
const POSTE_EDITEUR = `PC DE L'ÉDITEUR (directive du 02/11/2026) : dans « laisses », une entrée qui commence par « À faire sur le PC de l'éditeur : » liste chaque geste manuel que ce lot rend nécessaire sur son PC (Windows, XAMPP, PHP 8.3), dans l'ordre : commandes (git pull, composer install, npm install, npx playwright install chromium, php artisan migrate:fresh, php artisan optimize:clear, php artisan queue:listen…), et chaque variable de .env à ajouter, changer ou retirer, avec son nom, sa valeur quand elle n'est pas secrète, et sinon où l'obtenir (jamais une valeur secrète dans le dépôt, les notes ou un compte rendu) ; écris « À faire sur le PC de l'éditeur : rien » s'il n'y a rien. Tiens .env.example et la section d'installation du README à jour de chaque variable et de chaque commande nouvelles.`
const LOTS_AVEC_POSTE = ['TR', 'EX', 'QA', 'PG', 'TY1', 'TY2', 'TY3', 'PS1', 'PS2', 'CALC', 'FI', 'AUD', 'DEMO', 'UI', 'NAV-2', 'NAV-3', 'NAV-4', 'NAV-5', 'ML', 'DV', 'EC2', 'S9-L', 'S9-A', '21', 'SEED', 'ER-PRO', 'STAT', 'MAT-PRO', 'DEMO-V', 'REGLE-B', 'REGUL', 'DATEOP', 'DEVIS-RET', 'MDP', 'IDENT', 'CESSION', 'NAF25', 'VIES-DEP']
for (const l of LOTS) {
  if (LOTS_AVEC_POSTE.includes(l.id)) {
    l.complement = l.complement ? `${l.complement}\n\n${POSTE_EDITEUR}` : POSTE_EDITEUR
  }
}

// Décision de l'éditeur du 09/11/2026 (DIRECTIVES.md, D56) : après les lots TY1 à PS2, chaque lot garde Larastan au plus strict et Psalm au niveau 1.
// Ajoutée seulement aux lots qui suivent PS2, pour garder intactes les invites des lots déjà faits (reprise).
const STATIQUE = `ANALYSE STATIQUE (décision de l'éditeur du 09/11/2026, D56, ${S}/qualite/decision-statique.md, §§ 6 et 9) : les lots TY1 à PS2 ont mis Larastan au plus strict et Psalm au niveau 1. Avant chaque commit, en plus de la suite : env -u AI_AGENT -u CLAUDECODE -u CLAUDE_CODE vendor/bin/phpstan analyse --memory-limit=3G, puis Psalm (types et flux, et témoin, commandes du README, lancées depuis la racine du dépôt avec php8.4), puis php tests/Qualite/qualite.php seuils <(git -C ${DEPOT} show origin/${BRANCHE}:tests/Qualite/seuils.json) rendent 0. Ni @phpstan-ignore, ni @psalm-suppress, ni assert(), ni @var en ligne, ni conversion forcée, ni type élargi, ni exception de configuration nouvelle ; aucun niveau, aucune règle, aucune option, aucun chemin ni aucun stub de l'analyse ne baisse.`
const LOTS_APRES_STATIQUE = [] // D63 : Larastan et Psalm attendent l'étape 15
for (const l of LOTS) {
  if (LOTS_APRES_STATIQUE.includes(l.id)) {
    l.complement = l.complement ? `${l.complement}\n\n${STATIQUE}` : STATIQUE
  }
}

// Décision de l'éditeur du 13/11/2026 (« oui pour larastan et psalm sur github ») : à partir du lot STAT, Larastan et l'analyse des flux
// de Psalm tournent à chaque envoi dans la CI. Les lots qui suivent STAT lancent Larastan et les seuils avant leur commit ; Psalm flux reste à la CI.
// Ajoutée seulement aux lots qui n'avaient pas commencé, pour garder intactes les invites des lots déjà faits (reprise).
const STATIQUE_CI = `ANALYSE STATIQUE À CHAQUE ENVOI (décision de l'éditeur du 13/11/2026, lot STAT, CLAUDE.md protocole point 3) : avant ton commit, env -u AI_AGENT -u CLAUDECODE -u CLAUDE_CODE vendor/bin/phpstan analyse --memory-limit=3G puis php tests/Qualite/qualite.php seuils <(git -C ${DEPOT} show origin/${BRANCHE}:tests/Qualite/seuils.json) rendent 0 (sorties dans un fichier). Ni @phpstan-ignore, ni @psalm-suppress, ni assert(), ni @var en ligne, ni conversion forcée, ni type élargi, ni exception de configuration nouvelle ; aucun niveau, aucune règle, aucune option, aucun chemin ni aucun stub de l'analyse ne baisse. L'analyse des flux de Psalm tourne dans la CI ; si la CI de la tête poussée est rouge (tâches « Analyse statique et seuils » ou « Analyse des flux de données » comprises), répare-la d'abord.`
const LOTS_APRES_CI = ['MAT-PRO', 'DEMO-V', 'REGLE-B', 'REGUL', 'DATEOP', 'DEVIS-RET', 'MDP', 'IDENT', 'CESSION', 'NAF25', 'VIES-DEP']
for (const l of LOTS) {
  if (LOTS_APRES_CI.includes(l.id)) {
    l.complement = `${l.complement.replace('Larastan, Psalm, couverture et mutation non lancés (étape 15)', 'couverture et mutation non lancées (étape 15) ; Larastan : voir ANALYSE STATIQUE À CHAQUE ENVOI')}\n\n${STATIQUE_CI}`
  }
}

const APRES_CHAINE = ['SEED', 'ER-PRO', 'STAT', 'MAT-PRO', 'DEMO-V', 'REGLE-B', 'REGUL', 'DATEOP', 'DEVIS-RET', 'MDP', 'IDENT', 'CESSION', 'NAF25', 'VIES-DEP']
const OUVERTS = args && Array.isArray(args.ouverts) ? args.ouverts : []
const INCONNUS = OUVERTS.filter(id => !LOTS.some(l => l.id === id))
if (OUVERTS.length === 0 || INCONNUS.length > 0) {
  log(`Aucun lot lancé : args.ouverts doit être un tableau JSON de lots de LOTS (reçu : ${JSON.stringify(args)} ; inconnus : ${INCONNUS.join(', ') || 'aucun'})`)
  return []
}

// Reprise d'un lot déjà commité, arrêté en route (redémarrage, limite, pause) :
// args.reprise = { "<lot>": { "commit": "<debut>..<fin>" } } saute l'implémentation et relance les relectures sur cette plage ;
// avec "defauts": [ ... ] (ceux que les relectures ont déjà rendus, sauvés dans notes/reprises/), il saute aussi les relectures
// et passe directement à la correction (liste vide : directement à la poussée). Un script de course ne lit aucun fichier :
// les défauts arrivent par args.
const REPRISES = args && args.reprise && typeof args.reprise === 'object' && !Array.isArray(args.reprise) ? args.reprise : {}
const PLAGE_DE_COMMITS = /^[0-9a-f]{7,40}(\.\.[0-9a-f]{7,40})?$/
const CHAMPS_D_UN_DEFAUT = ['titre', 'fichier', 'scenario', 'correction', 'gravite']
const REPRISES_FAUSSES = Object.entries(REPRISES).filter(([id, r]) => !OUVERTS.includes(id) || !r || typeof r !== 'object'
  || typeof r.commit !== 'string' || !PLAGE_DE_COMMITS.test(r.commit)
  || (r.defauts !== undefined && (!Array.isArray(r.defauts) || r.defauts.some(d => !d || CHAMPS_D_UN_DEFAUT.some(c => typeof d[c] !== 'string'))))).map(([id]) => id)
if (REPRISES_FAUSSES.length > 0) {
  log(`Aucun lot lancé : args.reprise mal formé pour ${REPRISES_FAUSSES.join(', ')} (chaque reprise vise un lot de ouverts, avec "commit" = une plage « debut..fin » et, si ses relectures sont faites, "defauts" = la liste de leurs défauts)`)
  return []
}

// Une étape coupée par un redémarrage de la machine laisse ses modifications non commitées : la reprise les retrouve.
const TRAVAIL_COUPE = `Avant de commencer, regarde git status --short dans ${DEPOT} : s'il n'est pas vide, ce sont les modifications non commitées d'une tentative précédente de cette même étape, coupée par un redémarrage de la machine ; relis-les en entier, garde ce qui est juste, corrige ou retire le reste, puis termine le travail. Ne les jette jamais sans les avoir lues. Regarde aussi git log --oneline origin/${BRANCHE}..HEAD : des commits de ce même lot peuvent y être, faits par la tentative coupée ; ne les refais pas, relis-les, continue après eux, et ta plage « commit » les inclut (premier hash de cette liste..dernier).`

// Effort des agents qui écrivent, relisent et corrigent : décision de l'éditeur du 01/11/2026 (DIRECTIVES.md, D49) :
// Extra (xhigh) pour le travail courant, Max pour les lots sensibles, fixé ici par la session sans le lui redemander.
// Plage des commits d'un lot : l'agent qui écrit le lot la rend en « premier..dernier », premier compris,
// alors qu'en notation git « a..b » exclut a. Les relecteurs et la correction lisent donc les commits non poussés.
const COMMITS_DU_LOT = `Les commits de ce lot sont tous ceux qui ne sont pas encore poussés : lis git -C ${DEPOT} log --oneline origin/${BRANCHE}..HEAD et git -C ${DEPOT} diff origin/${BRANCHE}..HEAD (avant de commencer, git -C ${DEPOT} fetch origin ${BRANCHE} si la référence manque). Attention : la plage « premier..dernier » rendue par l'agent qui a écrit le lot comprend son premier commit, alors que git diff ou git log sur « premier..dernier » l'exclurait ; ne lis donc jamais cette plage telle quelle, et vérifie que tu vois bien chaque commit « (lot <id> k/n) » du lot.`

const LOTS_SENSIBLES = ['CALC'] // D63, réponse de l'éditeur du 11/11 vers 09 h 50 UTC : « max » seulement pour CALC, « extra » pour tous les autres lots
const effortDuLot = id => (LOTS_SENSIBLES.includes(id) ? 'max' : 'xhigh')

// Travail par parties (décision de l'éditeur du 11/11/2026, « 1 et 2 », DIRECTIVES.md D62) : l'agent qui écrit un lot
// relisait à chaque étape toute sa mémoire de travail, qui grossissait au fil du lot (TY1 : 1 562 étapes, environ
// 500 000 mots relus à chaque étape). Un lot est donc écrit par des agents successifs, chacun avec une mémoire neuve,
// qui se passent la main par une note de passage. Les lots déjà commencés avant cette décision gardent un seul agent.
const UN_SEUL_AGENT = ['QA', 'PG', 'TY1', 'TY2']
const MAX_PARTIES = 6
const PARTIE = {
  type: 'object',
  properties: {
    termine: { type: 'boolean' },
    commit: { type: 'string' },
    tests: { type: 'string' },
    faits: { type: 'array', items: { type: 'string' } },
    laisses: { type: 'array', items: { type: 'string' } },
    resume: { type: 'string' },
  },
  required: ['termine', 'commit', 'tests', 'faits', 'laisses', 'resume'],
}
const consigneDesParties = (id, note, partie) => `TRAVAIL PAR PARTIES (décision de l'éditeur du 11/11/2026, pour consommer moins sans rien changer aux tests ni aux relectures ; ${S}/historique/DIRECTIVES.md, D62). Ce lot est écrit par plusieurs agents successifs, chacun avec une mémoire neuve, qui se passent la main par la note de passage ${note}. Tu es l'agent de la partie ${partie}.${partie > 1 ? ` Lis d'abord cette note en entier (ce qui est fait, ce qui reste, les choix pris, les pièges, les commandes lancées et leurs résultats), puis l'état du dépôt : tu continues le travail là où la partie précédente l'a laissé, sans rien refaire de ce qui est commité.` : ''}
Arrête ta partie à un point propre dès que l'une de ces conditions est vraie, s'il reste du travail : (a) tu viens de faire un commit ; (b) tu as fait environ 300 actions (appels d'outils) dans cette partie. Point propre : aucun fichier laissé à moitié écrit ; les tests ciblés des fichiers touchés passent, ou ce qui ne passe pas encore est noté. Avant de rendre la main, crée le dossier de la note si besoin (mkdir -p) et ajoute à la note, sans effacer les parties précédentes, une section « Partie ${partie} » : ce qui est fait (commits, fichiers), ce qui reste dans l'ordre, les choix pris et pourquoi, les pièges trouvés, les commandes lancées avec leur durée et leur code de sortie, et les fichiers où sont gardées les sorties longues. Rends alors termine=false, avec dans commit la plage des commits du lot déjà faits (vide s'il n'y en a pas) et dans resume un court résumé de ta partie.
Quand tout le lot est fini (dernier commit fait, vérifications finales du cahier faites), rends termine=true avec le compte rendu de TOUT le lot, parties précédentes comprises (lis la note pour elles) : commit = la plage de tous les commits du lot, tests, faits et laisses de tout le lot.
Règles : la suite PostgreSQL complète au code 0 une seule fois, juste avant le commit du lot, sur l'arbre exact du commit (D63) ; un seul commit pour le lot ; les sorties longues des outils dans un fichier dont tu ne lis que le résumé et chaque erreur en entier (D62). Un lot moyen tient en une ou deux parties : ne coupe pas sans raison.`
async function implementationEnParties(lot, consigne) {
  const note = `${S}/passages/${lot.id}.md`
  for (let partie = 1; partie <= MAX_PARTIES; partie++) {
    const r = await agent(`${REGLES}\n\n${TRAVAIL_COUPE}\n\n${consigneDesParties(lot.id, note, partie)}\n\n${consigne}`, { label: partie === 1 ? `${lot.id}:implementation` : `${lot.id}:implementation-${partie}`, phase: lot.phase, schema: PARTIE, effort: effortDuLot(lot.id) })
    if (!r) {
      return null
    }
    if (r.termine) {
      return r
    }
    log(`Lot ${lot.id} : partie ${partie} rendue (${r.resume.slice(0, 160)}), la partie ${partie + 1} reprend par la note ${note}`)
  }
  log(`Lot ${lot.id} : ${MAX_PARTIES} parties sans fin du lot, arrêt pour inspection`)
  return null
}

const resultats = []
let phaseCourante = null
for (const lot of LOTS) {
  if (!OUVERTS.includes(lot.id)) {
    log(`Lot ${lot.id} : non demandé dans cette course, sauté`)
    continue
  }
  if (lot.phase !== phaseCourante) {
    phase(lot.phase)
    phaseCourante = lot.phase
  }
  const serie8 = !['SEED', 'ER-PRO', 'STAT', 'MAT-PRO', 'DEMO-V', 'REGUL', 'DATEOP', 'DEVIS-RET', 'MDP', 'IDENT', 'CESSION', 'NAF25', 'VIES-DEP', 'S9-L', 'S9-A', 'A5c', 'L1', 'A7', 'A7b', 'SL', 'QA', 'TY1', 'TY2', 'TY3', 'PS1', 'PS2', 'DV', 'NAV-1', 'NAV-2', 'NAV-3', 'NAV-4', 'NAV-5', 'UI', 'DEMO', 'ML', 'EC2', '21', 'T1', 'V2', 'EC', 'V2b', 'FA1', 'FA2', 'FA3', 'T2', 'T3', 'PU', 'TA'].includes(lot.id)
  const intitule = lot.id === '21' ? 'LOT DE DÉCISIONS 21 ÉTENDU' : ['TY1', 'TY2', 'TY3'].includes(lot.id) ? `LOT ${lot.id} DE L’ANALYSE STATIQUE (LARASTAN AU PLUS STRICT)` : ['PS1', 'PS2'].includes(lot.id) ? `LOT ${lot.id} DE L’ANALYSE STATIQUE (PSALM AU NIVEAU 1)` : lot.id === 'S9-L' ? 'LOT S9-L DE LA SÉRIE 9 (UN PRODUIT = UNE LIGNE)' : lot.id === 'S9-A' ? 'LOT S9-A DE LA SÉRIE 9 (« À FAIRE » AU TABLEAU DE BORD)' : lot.id === 'PU' ? 'LOT PU DE L’AFFICHAGE DES PRIX UNITAIRES' : lot.id === 'T3' ? 'LOT T3 DE L’HEURE LOCALE DES MAGASINS' : lot.id === 'T2' ? 'LOT T2 DES HORODATAGES SANS AMBIGUÏTÉ' : lot.id === 'V2b' ? 'LOT V2b DES COMPLÉMENTS DE LA VÉRIFICATION PAR COURRIER' : lot.id.startsWith('FA') ? `LOT ${lot.id} DE LA CONCURRENCE DES BROUILLONS ET DES FICHES` : lot.id === 'TA' ? 'LOT TA DES TYPES D’ACTIVITÉ' : lot.id === 'T1' ? 'LOT T1 DES TESTS DÉTERMINISTES' : lot.id === 'V2' ? 'LOT V2 DE LA VÉRIFICATION DES SOCIÉTÉS PAR COURRIER RECOMMANDÉ' : lot.id === 'EC' ? 'LOT EC DE L’ESPACE DES CABINETS D’EXPERTISE COMPTABLE' : lot.id === 'EC2' ? 'LOT EC2 DE L’EXPERT-COMPTABLE DE LA SOCIÉTÉ' : lot.id === 'ML' ? 'LOT ML DES E-MAILS VÉRIFIÉS SUR UN VRAI SERVEUR DE TEST' : lot.id === 'A7b' ? 'LOT A7b DES SUITES DU LOT A7 (RÉGULARISATION, SIREN D’UN CABINET)' : lot.id === 'SL' ? 'LOT SL DE L’ERREUR 419 DES FENÊTRES DE RECHERCHE' : lot.id === 'QA' ? 'LOT QA DES OUTILS DE QUALITÉ' : lot.id === 'DV' ? 'LOT DV DE LA RÉPONSE DU CLIENT À SON DEVIS EN LIGNE' : lot.id === 'UI' ? 'LOT UI DES DEMANDES DE L’ÉDITEUR SUR LES ÉCRANS' : lot.id === 'DEMO' ? 'LOT DEMO DE LA DÉMONSTRATION APRÈS LA VALIDATION' : lot.id.startsWith('NAV-') ? `LOT ${lot.id} DES TESTS EN NAVIGATEUR` : (serie8 ? `LOT ${lot.id} DE LA SÉRIE 8` : `LOT ${lot.id} DE L'ARCHITECTURE SOCIÉTÉ`)
  const parAvenant = lot.id === 'S8-V' || lot.id === 'A4c'
  const cadre = parAvenant ? `Applique en entier ce que ${S}/serie8/avenant-S8V-A4c.md prévoit pour ce lot (fichiers, migrations, classes, tests nommés, critères de fin, points de relecture, textes de CLAUDE.md de sa section 1), avec les règles communes de la section 3.2 de ${PLAN}.` : (serie8 ? `Applique en entier ce que la section 3.3 de ${PLAN} prévoit pour ce lot (fichiers, migrations, classes, tests nommés, critères de fin, points de relecture), avec les règles communes de la section 3.2, les textes de CLAUDE.md de la section 2 qu'il rend vrais, les rattachements de la section 3.4 qui le concernent et les corrections de l'annexe E.` : '')
  const consigne = `${intitule} : ${lot.titre}. ${cadre}${lot.complement ? `\n\n${lot.complement}` : ''}`
  const reprise = REPRISES[lot.id]
  const relecturesFaites = Boolean(reprise && Array.isArray(reprise.defauts))
  if (reprise) {
    log(`Lot ${lot.id} : implémentation déjà commitée (${reprise.commit}), ${relecturesFaites ? `relectures déjà faites (${reprise.defauts.length} défaut(s)), reprise à la correction` : 'reprise aux relectures'}`)
  }
  const rapport = reprise
    ? { commit: reprise.commit, tests: 'implémentation commitée avant la reprise', faits: [], laisses: [], resume: `Lot repris après un arrêt : commits ${reprise.commit}` }
    : (UN_SEUL_AGENT.includes(lot.id)
      ? await agent(`${REGLES}\n\n${TRAVAIL_COUPE}\n\n${consigne}`, { label: `${lot.id}:implementation`, phase: lot.phase, schema: RAPPORT, effort: effortDuLot(lot.id) })
      : await implementationEnParties(lot, consigne))
  if (!rapport || !rapport.commit) {
    log(`Lot ${lot.id} : aucun commit, arrêt de la chaîne pour inspection`)
    resultats.push({ lot: lot.id, rapport, revues: null, correction: null, poussee: null })
    break
  }
  const revues = relecturesFaites ? [{ defauts: reprise.defauts }] : (await parallel(OPTIQUES.map((optique, i) => () => agent(`Relecture adversariale du ou des commits ${rapport.commit} dans ${DEPOT} (${intitule} : ${lot.titre}).\n\n${COMMITS_DU_LOT}\n\nConsignes du lot :\n${REGLES}\n\n${consigne}\n\n${optique}\n\nLis ce diff en entier et le code autour. Reproduis chaque défaut par un test jetable dans tests/Feature/Scratch/ (exclu de git) que tu supprimes ensuite, par un essai réel (base PostgreSQL jetable que tu supprimes ensuite), ou par une lecture de code irréfutable. Ne signale que ce que tu as confirmé. Ne modifie aucun fichier suivi par git.`, { label: `${lot.id}:relecture${i + 1}`, phase: lot.phase, schema: REVUE, effort: effortDuLot(lot.id) })))).filter(Boolean)
  const defauts = revues.flatMap(r => r.defauts || [])
  if (!relecturesFaites && revues.length < OPTIQUES.length) {
    log(`Lot ${lot.id} : ${OPTIQUES.length - revues.length} relecture(s) sans résultat, arrêt de la chaîne pour inspection (rien n'est poussé)`)
    resultats.push({ lot: lot.id, rapport, revues, correction: null, poussee: null })
    break
  }
  let correction = null
  if (defauts.length > 0) {
    const titreCommit = lot.id === '21' ? 'Relecture du lot 21 des décisions' : ['TY1', 'TY2', 'TY3', 'PS1', 'PS2'].includes(lot.id) ? `Relecture du lot ${lot.id} de l’analyse statique` : lot.id === 'S9-L' ? 'Relecture du lot S9-L de la série 9' : lot.id === 'S9-A' ? 'Relecture du lot S9-A de la série 9' : lot.id === 'PU' ? 'Relecture du lot PU de l’affichage des prix unitaires' : lot.id === 'T3' ? 'Relecture du lot T3 de l’heure locale des magasins' : lot.id === 'T2' ? 'Relecture du lot T2 des horodatages' : lot.id === 'V2b' ? 'Relecture du lot V2b des compléments de la vérification' : lot.id.startsWith('FA') ? `Relecture du lot ${lot.id} de la concurrence des brouillons et des fiches` : lot.id === 'TA' ? 'Relecture du lot TA des types d’activité' : lot.id === 'T1' ? 'Relecture du lot T1 des tests déterministes' : lot.id === 'V2' ? 'Relecture du lot V2 de la vérification par courrier' : lot.id === 'EC' ? 'Relecture du lot EC de l’espace des cabinets' : lot.id === 'EC2' ? 'Relecture du lot EC2 de l’expert-comptable de la société' : lot.id === 'ML' ? 'Relecture du lot ML des e-mails vérifiés' : lot.id === 'A7b' ? 'Relecture du lot A7b des suites du lot A7' : lot.id === 'SL' ? 'Relecture du lot SL de l’erreur 419 des fenêtres de recherche' : lot.id === 'QA' ? 'Relecture du lot QA des outils de qualité' : lot.id === 'DV' ? 'Relecture du lot DV du devis en ligne' : lot.id === 'UI' ? 'Relecture du lot UI des écrans' : lot.id === 'DEMO' ? 'Relecture du lot DEMO de la démonstration' : lot.id.startsWith('NAV-') ? `Relecture du lot ${lot.id} des tests en navigateur` : APRES_CHAINE.includes(lot.id) ? `Relecture du lot ${lot.id}` : (serie8 ? `Relecture du lot ${lot.id} de la série 8` : `Relecture du lot ${lot.id} de l'architecture société`)
    correction = await agent(`${REGLES}\n\n${TRAVAIL_COUPE}\n\n${consigne}\n\nCORRECTION DE RELECTURE de ce lot (commits ${rapport.commit}).\n\n${COMMITS_DU_LOT}\n\nDeux relectures adversariales ont confirmé ces défauts (des doublons sont possibles) :\n${JSON.stringify(defauts, null, 2)}\n\nVérifie chacun, corrige ceux qui sont réels avec un test de régression, et explique pourquoi tu écartes les autres. Vérification de la correction (D63) : les tests ciblés des fichiers touchés et les tests de régression, au code 0, puis pint ; pas de suite complète (la CI GitHub la repasse après l'envoi, et le lot suivant répare d'abord une CI rouge). Fais un nouveau commit (ne réécris pas l'historique) titré « ${titreCommit} ».`, { label: `${lot.id}:correction`, phase: lot.phase, schema: RAPPORT, effort: effortDuLot(lot.id) })
  }
  if (defauts.length > 0 && (!correction || !correction.commit)) {
    log(`Lot ${lot.id} : correction de relecture sans résultat, arrêt de la chaîne pour inspection (rien n'est poussé)`)
    resultats.push({ lot: lot.id, rapport, revues, correction, poussee: null })
    break
  }
  const poussee = await agent(`Dans ${DEPOT}, vérifie que l'arbre de travail est propre (git status --short vide ; sinon ne pousse rien et explique pourquoi), puis pousse la branche avec git push -u origin ${BRANCHE}. En cas d'échec réseau uniquement, réessaie jusqu'à 4 fois en attendant 2, 4, 8 puis 16 secondes. Ne modifie aucun fichier, ne crée aucun commit, ne force jamais. Renvoie si la poussée a réussi et le hash de la tête poussée.`, { label: `${lot.id}:poussee`, phase: lot.phase, schema: POUSSEE, effort: 'low' })
  resultats.push({ lot: lot.id, rapport, revues, correction, poussee })
  if (!poussee || !poussee.pousse) {
    log(`Lot ${lot.id} : poussée non faite, arrêt de la chaîne pour inspection`)
    break
  }
  // D63 : la fiche de reprise n'est plus relue après chaque lot ; la session la tient à jour.
  await agent(`Lance exactement cette commande : bash ${S}/pilotage-sync.sh "Après le lot ${lot.id}" ; puis renvoie les trois dernières lignes de sa sortie. Ne modifie aucun autre fichier, ne touche ni au dépôt ${DEPOT} ni à sa branche ${BRANCHE}. Si la commande échoue, renvoie son message d'erreur sans rien tenter d'autre.`, { label: `${lot.id}:notes`, phase: lot.phase, effort: 'low' })
}
return resultats
